package com.alsafa.native4.core;

import android.content.ContentValues;
import android.database.sqlite.SQLiteDatabase;
import com.alsafa.native4.sync.SyncOperation;
import org.json.JSONObject;
import java.util.UUID;

/** Product media/barcodes and independent color variants. No automatic deletion or replacement. */
public final class ProductMediaStore {
 private final CoreStore.DbProvider provider;private final String deviceId;
 public ProductMediaStore(CoreStore.DbProvider provider,String deviceId){this.provider=provider;this.deviceId=deviceId;}
 public String addImage(String productId,String uri,int sortOrder)throws Exception{return addAsset("product_images","image_id",productId,"uri",uri,sortOrder);}
 public String addBarcode(String productId,String barcode,boolean customerQr)throws Exception{String b=req(barcode,"الباركود");long now=System.currentTimeMillis();String id="barcode-"+UUID.randomUUID();SQLiteDatabase db=provider.db();db.beginTransaction();try{ContentValues v=new ContentValues();v.put("barcode_id",id);v.put("product_id",productId);v.put("barcode",b);v.put("kind",customerQr?"CUSTOMER_QR":"SELLER");v.put("created_at",now);db.insertOrThrow("product_barcodes",null,v);sync(db,id,new JSONObject().put("barcodeId",id).put("productId",productId).put("barcode",b).put("kind",customerQr?"CUSTOMER_QR":"SELLER").put("updatedAt",now));db.setTransactionSuccessful();return id;}finally{db.endTransaction();}}
 public String createVariant(String parentId,String name,String barcode,String dial,String caseColor,String strap,int qty,double salePrice,double costPrice,String currency)throws Exception{if(qty<0||salePrice<0||costPrice<0)throw new IllegalArgumentException("الكمية أو السعر غير صالح");String n=req(name,"اسم المنتج");long now=System.currentTimeMillis();String id="product-"+UUID.randomUUID();SQLiteDatabase db=provider.db();db.beginTransaction();try{ContentValues v=new ContentValues();v.put("product_id",id);v.put("name",n);v.put("barcode",trim(barcode));v.put("variant_type","ADDITIONAL");v.put("parent_product_id",parentId);v.put("dial_color",trim(dial));v.put("case_color",trim(caseColor));v.put("strap_color",trim(strap));v.put("quantity",qty);v.put("sale_price",salePrice);v.put("cost_price",costPrice);v.put("currency",currency(currency));v.put("created_at",now);v.put("updated_at",now);db.insertOrThrow("products",null,v);JSONObject j=new JSONObject().put("productId",id).put("parentProductId",parentId).put("variantType","ADDITIONAL").put("name",n).put("barcode",trim(barcode)).put("dialColor",trim(dial)).put("caseColor",trim(caseColor)).put("strapColor",trim(strap)).put("quantity",qty).put("salePrice",salePrice).put("costPrice",costPrice).put("currency",currency(currency)).put("updatedAt",now);provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.PRODUCT_CREATE,id,j.toString(),deviceId));db.setTransactionSuccessful();return id;}finally{db.endTransaction();}}
 private String addAsset(String table,String idCol,String productId,String col,String value,int sort)throws Exception{String val=req(value,"الصورة");long now=System.currentTimeMillis();String id="image-"+UUID.randomUUID();SQLiteDatabase db=provider.db();db.beginTransaction();try{ContentValues v=new ContentValues();v.put(idCol,id);v.put("product_id",productId);v.put(col,val);v.put("sort_order",sort);v.put("created_at",now);db.insertOrThrow(table,null,v);sync(db,id,new JSONObject().put("imageId",id).put("productId",productId).put("uri",val).put("sortOrder",sort).put("updatedAt",now));db.setTransactionSuccessful();return id;}finally{db.endTransaction();}}
 private void sync(SQLiteDatabase db,String id,JSONObject j)throws Exception{provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.PRODUCT_UPDATE,id,j.toString(),deviceId));}
 private static String currency(String v){String x=trim(v).toUpperCase();return x.equals("TRY")||x.equals("SYP")?x:"USD";}private static String req(String v,String l){String s=trim(v);if(s.isEmpty())throw new IllegalArgumentException(l+" مطلوب");return s;}private static String trim(String v){return v==null?"":v.trim();}
}
